window.RF_FULL=window.RF_FULL||{};window.RF_FULL["plenum8-2014"]=[
["0","Преамбула","","","О ПРАКТИКЕ ПРИМЕНЕНИЯ СУДАМИ ЗАКОНОДАТЕЛЬСТВА О ВОИНСКОЙ ОБЯЗАННОСТИ, ВОЕННОЙ СЛУЖБЕ И СТАТУСЕ ВОЕННОСЛУЖАЩИХ В целях обеспечения единства практики применения судами законодательства о воинской обязанности, военной службе и статусе военнослужащих, а также учитывая возникающие у судов при рассмотрении данной категории дел вопросы, Пленум Верховного Суда Российской Федерации, руководствуясь статьей 126 Конституции Российской Федерации, статьями 2 и 5 Федерального конституционного закона от 5 февраля 2014 года N 3-ФКЗ \"О Верховном Суде Российской Федерации\", постановляет дать следующие разъяснения:\nПодсудность военным судам административных и гражданских дел, дел об административных правонарушениях и материалов о грубых дисциплинарных проступках"],
["1","В силу статьи 7 Федерального конституционного закона от 23 июня 1999 года N 1-ФКЗ \"О военных судах Российской Федерации\" (далее - Федеральный…","","","1. В силу статьи 7 Федерального конституционного закона от 23 июня 1999 года N 1-ФКЗ \"О военных судах Российской Федерации\" (далее - Федеральный конституционный закон \"О военных судах Российской Федерации\"), статьи 18 Кодекса административного судопроизводства Российской Федерации (далее - КАС РФ), статьи 25 Гражданского процессуального кодекса Российской Федерации (далее - ГПК РФ), статьи 4 Федерального закона от 1 декабря 2006 года N 199-ФЗ \"О судопроизводстве по материалам о грубых дисциплинарных проступках при применении к военнослужащим дисциплинарного ареста и об исполнении дисциплинарного ареста\", статьи 22 Федерального закона от 27 мая 1998 года N 76-ФЗ \"О статусе военнослужащих\" (далее - Федеральный закон \"О статусе военнослужащих\") дела, связанные с защитой нарушенных и (или) оспариваемых прав, свобод и охраняемых законом интересов военнослужащих, граждан, проходящих военные сборы, в том числе граждан, пребывающих в мобилизационном людском резерве, граждан, пребывающих в добровольческих формированиях, от действий (бездействия) органов военного управления, воинских должностных лиц и принятых ими решений, подсудны военным судам.\nЛица, уволенные с военной службы, граждане, прошедшие военные сборы, в том числе пребывавшие в мобилизационном людском резерве, граждане, исключенные из добровольческих формирований, вправе оспаривать в военных судах действия (бездействие) органов военного управления, воинских должностных лиц и принятые ими решения, которыми нарушены права, свободы и охраняемые законом интересы указанных лиц в период прохождения военной службы, военных сборов, пребывания в добровольческих формированиях.\nДела об административных правонарушениях, указанных в частях 1 - 2 статьи 23.1 Кодекса Российской Федерации об административных правонарушениях (далее - КоАП РФ) и совершенных военнослужащими и гражданами, призванными на военные сборы, рассматриваются судьями гарнизонных военных судов.\nАбзац исключен. - Постановление Пленума Верховного Суда РФ от 28.10.2025 N 21.\nДела по искам к военнослужащим, лицам, уволенным с военной службы, гражданам, проходящим или прошедшим военные сборы, в том числе гражданам, пребывающим в мобилизационном людском резерве или исключенным из него, гражданам, пребывающим в добровольческих формированиях, о возмещении ущерба, причиненного ими при исполнении обязанностей военной службы либо в период прохождения военных сборов, в период пребывания в добровольческих формированиях, по основаниям, установленным статьями 8, 9, 12.1 Федерального закона от 12 июля 1999 года N 161-ФЗ \"О материальной ответственности военнослужащих\" (далее - Федеральный закон \"О материальной ответственности военнослужащих\"), подсудны военным судам.\nСудьи гарнизонных военных судов осуществляют судопроизводство по материалам о грубых дисциплинарных проступках при применении к военнослужащим и гражданам, призванным на военные сборы, дисциплинарного ареста и об исполнении дисциплинарного ареста.\nСудам следует иметь в виду, что применение дисциплинарного ареста в порядке, установленном Федеральным законом от 8 августа 2024 года N 231-ФЗ \"Об особенностях применения и исполнения дисциплинарного ареста в отношении военнослужащих, принимающих участие в специальной военной операции\", может быть оспорено в военном суде.\nВ силу части 4 статьи 7 Федерального конституционного закона \"О военных судах Российской Федерации\" военным судам, дислоцированным за пределами территории Российской Федерации, подсудны все гражданские, административные и уголовные дела, подлежащие рассмотрению судами общей юрисдикции, если иное не установлено международным договором Российской Федерации."],
["2","При принятии административных исковых заявлений и исковых заявлений к производству суда необходимо иметь в виду, что в качестве административных…","","","2. При принятии административных исковых заявлений и исковых заявлений к производству суда необходимо иметь в виду, что в качестве административных истцов (истцов) могут выступать военнослужащие, граждане, проходящие или прошедшие военные сборы, в том числе граждане, пребывающие в мобилизационном людском резерве или исключенные из него, граждане, пребывающие в добровольческих формированиях или исключенные из добровольческих формирований, и лица, уволенные с военной службы, органы военного управления и воинские должностные лица, а в качестве административных ответчиков (ответчиков) - органы военного управления и воинские должностные лица, а также военнослужащие, граждане, проходящие или прошедшие военные сборы, в том числе граждане, пребывающие в мобилизационном людском резерве или исключенные из него, граждане, пребывающие в добровольческих формированиях или исключенные из добровольческих формирований, и лица, уволенные с военной службы (например, по основаниям, установленным Федеральным законом \"О материальной ответственности военнослужащих\").\nВоеннослужащими являются граждане Российской Федерации, не имеющие гражданства (подданства) иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина на территории иностранного государства, которые проходят военную службу в Вооруженных Силах Российской Федерации и в войсках национальной гвардии Российской Федерации (далее также - другие войска), в спасательных воинских формированиях федерального органа исполнительной власти, уполномоченного на решение задач в области гражданской обороны (далее также - воинские формирования), в Службе внешней разведки Российской Федерации, органах федеральной службы безопасности, органах государственной охраны, органах военной прокуратуры, военных следственных органах Следственного комитета Российской Федерации и федеральном органе обеспечения мобилизационной подготовки органов государственной власти Российской Федерации (далее - органы), в воинских подразделениях федеральной противопожарной службы и создаваемых на военное время специальных формированиях, а также граждане, имеющие гражданство (подданство) иностранного государства либо вид на жительство или иной документ, подтверждающий право на постоянное проживание гражданина на территории иностранного государства, иностранные граждане и лица без гражданства, которые проходят военную службу в Вооруженных Силах Российской Федерации и воинских формированиях.\nВ случаях, предусмотренных федеральными законами и нормативными правовыми актами Президента Российской Федерации, военнослужащие могут проходить военную службу не на воинских должностях в международных организациях, организациях, осуществляющих деятельность в интересах обороны страны и безопасности государства, и в военных учебных центрах при федеральных государственных образовательных организациях высшего образования. В силу статьи 19 Положения о порядке прохождения военной службы, утвержденного Указом Президента Российской Федерации от 16 сентября 1999 года N 1237 (далее - Положение о порядке прохождения военной службы), в качестве ответчиков (заинтересованных лиц) по искам и заявлениям военнослужащих, проходящих военную службу не на воинских должностях, могут выступать как руководители соответствующих организаций (например, по вопросам освобождения от должности), так и органы военного управления, воинские должностные лица (например, по вопросам увольнения с военной службы).\nГражданами, пребывающими в добровольческих формированиях, являются граждане Российской Федерации, добровольно поступившие в добровольческие формирования, заключившие контракт о пребывании в добровольческом формировании (о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации) в соответствии с Федеральным законом от 31 мая 1996 года N 61-ФЗ \"Об обороне\" (далее - Федеральный закон \"Об обороне\").\nК органам военного управления относятся Министерство обороны Российской Федерации, иной федеральный орган исполнительной власти (федеральный государственный орган), в котором федеральным законом предусмотрена военная служба, центральные органы военного управления (командования, штабы, управления, департаменты, службы, отделы, отряды, центры), территориальные органы военного управления (военные комиссариаты, региональные центры, комендатуры территорий), управления и штабы объединений, соединений, воинских частей Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов.\nПод воинскими должностными лицами понимаются должностные лица органов военного управления, командиры (начальники) воинских частей, начальники органов военной полиции, начальники гарнизонов, иные лица, постоянно, временно или по специальному полномочию выступающие от имени Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, в которых федеральным законом предусмотрена военная служба, осуществляющие функции представителя власти либо выполняющие организационно-распорядительные, административно-хозяйственные функции, принявшие оспариваемое решение, совершившие оспариваемые действия (бездействие), имеющие обязательный характер и затрагивающие права и свободы заявителей, в том числе руководители управлений, департаментов, учреждений и организаций Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов."],
["3","В силу пункта 10 статьи 38 Федерального закона от 28 марта 1998 года N 53-ФЗ \"О воинской обязанности и военной службе\" граждане приобретают статус…","","","3. В силу пункта 10 статьи 38 Федерального закона от 28 марта 1998 года N 53-ФЗ \"О воинской обязанности и военной службе\" граждане приобретают статус военнослужащего с момента начала военной службы, который исчисляется:\nдля граждан, не пребывающих в запасе, призванных на военную службу, - со дня присвоения воинского звания рядового;\nдля граждан (иностранных граждан, лиц без гражданства), поступивших на военную службу по контракту, - со дня вступления в силу контракта о прохождении военной службы;\nдля граждан, не проходивших военную службу или прошедших военную службу ранее и поступивших в военные профессиональные образовательные организации или военные образовательные организации высшего образования, - с даты зачисления в указанные образовательные организации.\nОкончанием военной службы считается дата исключения военнослужащего из списков личного состава воинской части.\nВ силу положений статьи 22.1 Федерального закона \"Об обороне\" граждане Российской Федерации приобретают статус участника добровольческого формирования со дня заключения контракта о пребывании в добровольческом формировании (о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации) между гражданином Российской Федерации и Министерством обороны Российской Федерации (Федеральной службой войск национальной гвардии Российской Федерации), а днем окончания пребывания в добровольческом формировании считается день исключения гражданина Российской Федерации из добровольческого формирования по одному из оснований, предусмотренных пунктами 7 - 9 данной статьи.\nНа граждан, призванных на военные сборы, граждан, пребывающих в мобилизационном людском резерве, в соответствии с пунктом 2 статьи 2 Федерального закона \"О статусе военнослужащих\" и граждан, пребывающих в добровольческих формированиях, в соответствии с пунктом 10 статьи 22.1 Федерального закона \"Об обороне\" статус военнослужащего распространяется только в случаях и в порядке, которые предусмотрены федеральными законами и иными нормативными правовыми актами Российской Федерации."],
["4","При решении вопроса об уплате органом военного управления государственной пошлины при обращении в суд необходимо учитывать льготы, предусмотренные…","","","4. При решении вопроса об уплате органом военного управления государственной пошлины при обращении в суд необходимо учитывать льготы, предусмотренные Налоговым кодексом Российской Федерации (далее - НК РФ). Разрешая вопрос, относится ли орган военного управления к государственному органу, имеющему льготу по уплате государственной пошлины, следует применять то значение понятия государственного органа, которое используется в соответствующей отрасли законодательства. Так, органы военного управления, созданные в целях обороны и безопасности государства, относятся к государственным органам, освобождаемым от уплаты государственной пошлины в соответствии с подпунктом 19 пункта 1 статьи 333.36 НК РФ, при выступлении в качестве истцов (административных истцов) или ответчиков (административных ответчиков).\nВетераны военной службы и ветераны боевых действий при обращении в суд за защитой своих прав, установленных законодательством о ветеранах, освобождаются от уплаты государственной пошлины с учетом положений, предусмотренных подпунктом 3 пункта 2 статьи 333.36 НК РФ."],
["5","При подготовке административных и гражданских дел к судебному разбирательству необходимо учитывать, что процессуальным законодательством…","","","5. При подготовке административных и гражданских дел к судебному разбирательству необходимо учитывать, что процессуальным законодательством предусмотрены различия в порядке рассмотрения дел, возникающих из публичных и иных правоотношений, в связи с чем особое значение приобретает правильное установление характера правоотношений сторон.\nВоенная служба, прохождение военных сборов, пребывание в добровольческих формированиях предполагают осуществление полномочий государства по обеспечению своего суверенитета и иных важнейших государственных интересов, а правоотношения, связанные с исполнением военнослужащими, гражданами, проходящими военные сборы, в том числе гражданами, пребывающими в мобилизационном людском резерве, и гражданами, пребывающими в добровольческих формированиях, общих, должностных и специальных обязанностей, являются публично-правовыми.\nТаким образом, нормы главы 22 раздела IV КАС РФ применяются, когда требования указанных лиц вытекают из военно-служебных правоотношений, основанных на властных полномочиях одной стороны по отношению к другой.\nВ тех случаях, когда оспариваемые действия совершены органами военного управления и воинскими должностными лицами в процессе осуществления иной деятельности, основанной на равенстве участников правоотношений, дело подлежит рассмотрению в порядке гражданского судопроизводства."],
["6","Административное исковое заявление (далее - заявление) об оспаривании решений, действий (бездействия) органов военного управления и воинских…","","","6. Административное исковое заявление (далее - заявление) об оспаривании решений, действий (бездействия) органов военного управления и воинских должностных лиц исходя из положений части 1 статьи 4 и части 1 статьи 219 КАС РФ подается в военный суд в трехмесячный срок со дня, когда административному истцу стало известно о нарушении его прав, свобод и законных интересов.\nПропуск данного срока не является для суда основанием для отказа в принятии заявления, но при отсутствии уважительных причин, которые подлежат выяснению судом в предварительном судебном заседании или в судебном заседании независимо от того, ссылались ли на это обстоятельство заинтересованные лица, может являться основанием для отказа в удовлетворении заявления с указанием в мотивировочной части решения только на установление судом данного обстоятельства."],
["7","При рассмотрении споров, связанных с прохождением военной службы, судам следует учитывать, что в силу частей 1 и 4 статьи 15, статьи 120 Конституции…","","","7. При рассмотрении споров, связанных с прохождением военной службы, судам следует учитывать, что в силу частей 1 и 4 статьи 15, статьи 120 Конституции Российской Федерации суд обязан разрешать дела на основании Конституции Российской Федерации, федеральных конституционных законов, федеральных законов и иных нормативных правовых актов, а также на основании общепризнанных принципов и норм международного права и международных договоров Российской Федерации, являющихся составной частью ее правовой системы.\nПри этом необходимо иметь в виду, что порядок прохождения военной службы, в частности заключение контракта о прохождении военной службы, прекращение его действия, поступление на военную службу и увольнение с нее, назначение на воинские должности и освобождение от воинских должностей, порядок пребывания на военных сборах, в том числе призыв на военные сборы и их окончание, порядок пребывания в мобилизационном людском резерве и исключения из него, порядок пребывания в добровольческих формированиях (заключение контракта о пребывании в добровольческом формировании, исключение из добровольческого формирования), порядок привлечения к дисциплинарной и материальной ответственности военнослужащих, граждан, пребывающих на военных сборах, в том числе граждан, пребывающих в мобилизационном людском резерве, и граждан, пребывающих в добровольческих формированиях, а также иные правоотношения, имеющие специфический характер в условиях военной службы (прохождения военных сборов, пребывания в добровольческих формированиях), регулируются федеральными законами и иными нормативными правовыми актами (в том числе нормативными правовыми актами федеральных органов исполнительной власти и федеральных государственных органов, в которых федеральным законом предусмотрена военная служба), определяющими порядок прохождения военной службы, порядок пребывания в добровольческих формированиях, а также правовой статус указанных лиц.\nНормы трудового законодательства могут применяться к правоотношениям, связанным с прохождением военной службы, лишь в случаях, когда об этом имеется прямое указание в законе (например, часть 8 статьи 11 Трудового кодекса Российской Федерации (далее - ТК РФ): трудовое законодательство и иные акты, содержащие нормы трудового права, не распространяются на военнослужащих при исполнении ими обязанностей военной службы).\nАбзац исключен. - Постановление Пленума Верховного Суда РФ от 28.10.2025 N 21.\nКонтракт о прохождении военной службы"],
["8","В соответствии со статьей 4 ТК РФ работа, выполнение которой обусловлено законодательством о воинской обязанности и военной службе, не входит в…","","","8. В соответствии со статьей 4 ТК РФ работа, выполнение которой обусловлено законодательством о воинской обязанности и военной службе, не входит в понятие принудительного труда.\nВ силу пункта 1 статьи 10 Федерального закона \"О статусе военнослужащих\" и пункта 3 статьи 32 Федерального закона \"О воинской обязанности и военной службе\" право на труд реализуется военнослужащими путем добровольного поступления на военную службу по контракту, условия которого включают в себя обязанность гражданина проходить военную службу в Вооруженных Силах Российской Федерации, других войсках, воинских формированиях или органах в течение установленного контрактом срока, определяемого командиром (начальником) воинской части на основании закона с учетом мнения лица, заключающего контракт, добросовестно исполнять все общие, должностные и специальные обязанности военнослужащих, установленные законодательными и иными нормативными правовыми актами Российской Федерации, а также право гражданина на соблюдение его прав и прав членов его семьи, включая получение социальных гарантий и компенсаций, установленных законодательными и иными нормативными правовыми актами Российской Федерации, определяющими статус военнослужащих и порядок прохождения военной службы.\nВ связи с изложенным судам следует исходить из того, что предъявление к военнослужащим специальных требований, обусловленных особенностями военной службы, в том числе неукоснительное соблюдение воинской дисциплины, необходимость некоторых ограничений их прав и свобод, установленных федеральными законами, не может рассматриваться как нарушение прав военнослужащих свободно распоряжаться своими способностями к труду, выбирать род деятельности и профессию."],
["9","Исходя из положений абзаца первого пункта 1 статьи 23 Федерального закона \"О статусе военнослужащих\" и пункта 5 статьи 34 Федерального закона \"О…","","","9. Исходя из положений абзаца первого пункта 1 статьи 23 Федерального закона \"О статусе военнослужащих\" и пункта 5 статьи 34 Федерального закона \"О воинской обязанности и военной службе\" военнослужащим не может быть отказано в заключении нового контракта о прохождении военной службы, если они не достигли предельного возраста пребывания на военной службе, не приобрели права на пенсию за выслугу лет и отсутствуют основания для их досрочного увольнения с военной службы, установленные Федеральным законом \"О воинской обязанности и военной службе\", и обстоятельства, когда с такими военнослужащими в силу закона не может быть заключен новый контракт.\nАбзац исключен. - Постановление Пленума Верховного Суда РФ от 28.10.2025 N 21."],
["10","В силу статьи 148 Уголовно-исполнительного кодекса Российской Федерации (далее - УИК РФ) до истечения установленного приговором суда срока наказания…","","","10. В силу статьи 148 Уголовно-исполнительного кодекса Российской Федерации (далее - УИК РФ) до истечения установленного приговором суда срока наказания военнослужащий, осужденный к ограничению по военной службе, может быть уволен с военной службы по основаниям и в порядке, которые предусмотрены Федеральным законом \"О воинской обязанности и военной службе\" и Положением о порядке прохождения военной службы. В случае если до истечения установленного приговором суда срока наказания в виде ограничения по военной службе у осужденного военнослужащего истекает срок контракта, новый контракт с таким военнослужащим не заключается и такой военнослужащий подлежит увольнению с военной службы по истечении срока контракта. В этих случаях командир воинской части направляет представление в суд о замене оставшейся неотбытой части наказания более мягким видом наказания либо об освобождении от наказания.\nРассмотрение такого представления командира воинской части согласно пункту 19 статьи 397 Уголовно-процессуального кодекса Российской Федерации (далее - УПК РФ) относится к вопросам, связанным с исполнением приговора, и осуществляется в порядке главы 47 УПК РФ."],
["11","Исходя из положений пункта 11 статьи 38 Федерального закона \"О воинской обязанности и военной службе\" судам необходимо учитывать, что военнослужащий,…","","","11. Исходя из положений пункта 11 статьи 38 Федерального закона \"О воинской обязанности и военной службе\" судам необходимо учитывать, что военнослужащий, заключая контракт, добровольно принимает на себя ряд обязанностей, которые отсутствуют в других видах трудовой деятельности, в частности обязанность продолжать военную службу после истечения срока, предусмотренного в контракте, в случаях, указанных в законе (например, при объявлении мобилизации (пункт 5 статьи 17 Федерального закона от 26 февраля 1997 года N 31-ФЗ \"О мобилизационной подготовке и мобилизации в Российской Федерации\" (далее - Федеральный закон \"О мобилизационной подготовке и мобилизации в Российской Федерации\").\nПри разрешении споров о правомерности нахождения военнослужащего на военной службе после истечения срока контракта судам следует исходить из того, что если после истечения срока, указанного в контракте, военнослужащий продолжает прохождение военной службы, например, до обеспечения его жилым помещением, то при отсутствии письменного согласия военнослужащего на увольнение с военной службы до обеспечения его жилым помещением (например, при отсутствии рапорта и др.) такого военнослужащего следует считать проходящим военную службу в добровольном порядке только до реализации его права на жилище. При совершении в указанный период правонарушения такой военнослужащий в зависимости от характера и тяжести содеянного подлежит привлечению к дисциплинарной, административной, материальной, гражданско-правовой или уголовной ответственности в соответствии с федеральными законами."],
["12","Предусмотренный пунктом 11 статьи 38 Федерального закона \"О воинской обязанности и военной службе\" запрет исключения военнослужащего из списков…","","","12. Предусмотренный пунктом 11 статьи 38 Федерального закона \"О воинской обязанности и военной службе\" запрет исключения военнослужащего из списков личного состава в день истечения срока военной службы, если в отношении такого военнослужащего, являющегося подозреваемым или обвиняемым в совершении преступления, избрана мера пресечения в виде заключения под стражу с содержанием на гауптвахте или наблюдения командования воинской части, представляет собой меру обеспечительного характера, обусловленную проведением в отношении этого военнослужащего предварительного расследования, которая может применяться только на основании УПК РФ.\nПри избрании в отношении военнослужащих, подозреваемых, обвиняемых в совершении преступления, таких уголовно-процессуальных мер пресечения, как наблюдение командования воинской части или заключение под стражу с содержанием на гауптвахте, отказ командира (начальника) воинской части в исключении военнослужащих из списков личного состава воинской части в день истечения срока их военной службы не может рассматриваться как ограничение прав военнослужащих и нарушение закона.\nНазначение на воинские должности. Зачисление военнослужащих в распоряжение командиров (начальников)"],
["13","Согласно пункту 1 статьи 43 Федерального закона \"О воинской обязанности и военной службе\" назначение на воинские должности военнослужащих, для…","","","13. Согласно пункту 1 статьи 43 Федерального закона \"О воинской обязанности и военной службе\" назначение на воинские должности военнослужащих, для которых штатом предусмотрены воинские звания до полковника или капитана 1 ранга включительно, в том числе связанное с переводом в другую местность для прохождения военной службы, осуществляется в порядке, установленном Положением о порядке прохождения военной службы.\nИсходя из содержания пункта 2 статьи 15 Положения о порядке прохождения военной службы военнослужащий, проходящий военную службу по контракту, может быть переведен к новому месту военной службы по служебной необходимости с назначением на равную воинскую должность без его согласия, что обусловлено спецификой военной службы и само по себе не может рассматриваться как нарушение его прав и свобод.\nВместе с тем данное обстоятельство не предполагает возможность произвольного перевода такого военнослужащего в другую воинскую часть (в другую местность), поскольку статья 15 Положения о порядке прохождения военной службы устанавливает исчерпывающий перечень случаев и условий, при которых военнослужащие могут быть переведены к новому месту службы из одной воинской части в другую, в том числе находящуюся в другой местности."],
["14","С учетом того, что международными соглашениями Российской Федерации со странами пребывания российских военных баз, воинских формирований (далее -…","","","14. С учетом того, что международными соглашениями Российской Федерации со странами пребывания российских военных баз, воинских формирований (далее - военные базы) определена организационно-штатная структура военных баз и их штатная численность, нахождение российских военнослужащих на территории стран пребывания военных баз вне состава и их штатной численности не предусмотрено.\nВ связи с изложенным судам при разрешении споров в отношении военнослужащих, освобожденных от воинских должностей, необходимо учитывать, что зачисление их в распоряжение командиров (начальников) на территории военных баз не производится и вопросы дальнейшего прохождения ими военной службы должны решаться путем плановой замены либо путем увольнения с военной службы или зачисления в распоряжение командиров (начальников) на территории Российской Федерации в пределах срока нахождения в распоряжении."],
["15","Разрешая споры о реализации военнослужащими прав, социальных гарантий и компенсаций, предоставляемых федеральными законами и иными нормативными…","","","15. Разрешая споры о реализации военнослужащими прав, социальных гарантий и компенсаций, предоставляемых федеральными законами и иными нормативными правовыми актами об охране семьи, материнства и детства, судам необходимо учитывать положение пункта 19 статьи 11 Положения о порядке прохождения военной службы о том, что беременные военнослужащие женского пола в соответствии с медицинским заключением с их согласия могут быть назначены на воинские должности с более легкими условиями службы с сохранением месячного оклада в соответствии с занимаемой воинской должностью, месячных и иных дополнительных выплат по воинской должности, которую они занимали до указанного назначения.\nВоеннослужащие женского пола, имеющие детей в возрасте до полутора лет, в соответствии с пунктом 20 статьи 11 Положения о порядке прохождения военной службы в случае, если они не могут выполнять служебные обязанности, назначаются на другую воинскую должность до достижения ребенком возраста полутора лет с сохранением месячного оклада в соответствии с занимаемой воинской должностью, месячных и иных дополнительных выплат по воинской должности, которую они занимали до назначения."],
["16","По смыслу статьи 145 УИК РФ, военнослужащие, отбывающие наказание в виде ограничения по военной службе, не могут быть назначены на высшую воинскую…","","","16. По смыслу статьи 145 УИК РФ, военнослужащие, отбывающие наказание в виде ограничения по военной службе, не могут быть назначены на высшую воинскую должность. Если с учетом характера совершенного преступления и иных обстоятельств военнослужащий, которому назначено наказание в виде ограничения по военной службе, не может быть оставлен в воинской должности, связанной с руководством подчиненными, он по решению соответствующего воинского должностного лица назначается на другую воинскую должность в пределах воинской части либо с переводом в другую воинскую часть или местность в соответствии с Положением о порядке прохождения военной службы, о чем извещается суд, вынесший приговор.\nДенежное довольствие и иные выплаты"],
["17","В соответствии с частями 1, 2 и 28 статьи 2 Федерального закона от 7 ноября 2011 года N 306-ФЗ \"О денежном довольствии военнослужащих и…","","","17. В соответствии с частями 1, 2 и 28 статьи 2 Федерального закона от 7 ноября 2011 года N 306-ФЗ \"О денежном довольствии военнослужащих и предоставлении им отдельных выплат\" и пунктами 10 и 11 статьи 38 Федерального закона \"О воинской обязанности и военной службе\" денежное довольствие военнослужащих, проходящих военную службу по контракту, является основным средством их материального обеспечения и стимулирования исполнения обязанностей военной службы и подлежит выплате с момента начала военной службы по день их исключения из списков личного состава воинской части в связи с окончанием военной службы.\nСудам необходимо учитывать, что денежное довольствие и другие выплаты считаются выданными военнослужащему в день их получения в финансовой службе воинской части (уполномоченном финансовом органе) либо в день поступления (зачисления) денежных средств на банковский (карточный) счет военнослужащего.\nПри подготовке к судебному разбирательству дел по заявлениям военнослужащих об оспаривании размера и состава выплачиваемого денежного довольствия, иных выплат суд должен выяснять, какой орган на основании статьи 158 Бюджетного кодекса Российской Федерации как главный распорядитель (распорядитель) бюджетных средств должен выступать в суде от имени органа военного управления или воинского должностного лица (например, финансово-экономические органы (службы) Министерства обороны Российской Федерации и др.), и надлежащим образом извещать его о времени и месте судебного заседания."],
["18","При рассмотрении дел, связанных с невыплатой (выплатой не в полном объеме) денежного довольствия в период нахождения военнослужащих, проходящих…","","","18. При рассмотрении дел, связанных с невыплатой (выплатой не в полном объеме) денежного довольствия в период нахождения военнослужащих, проходящих военную службу по контракту, в распоряжении командира (начальника), судам следует учитывать, что в этот период военнослужащим выплачиваются оклад по воинскому званию, оклад по последней занимаемой воинской должности и ежемесячная надбавка за выслугу лет в порядке, предусмотренном руководителем федерального органа исполнительной власти (федерального государственного органа), в котором федеральным законом предусмотрена военная служба, а при прохождении военной службы в районах Крайнего Севера и приравненных к ним местностях, а также в других местностях с неблагоприятными климатическими или экологическими условиями, в том числе в отдаленных местностях, высокогорных районах, пустынных и безводных местностях, выплачивается денежное довольствие с учетом коэффициентов и процентных надбавок (части 24 и 28 статьи 2 Федерального закона \"О денежном довольствии военнослужащих и предоставлении им отдельных выплат\").\nИстечение срока нахождения военнослужащего в распоряжении командира (начальника), предусмотренного пунктом 4 статьи 42 Федерального закона \"О воинской обязанности и военной службе\" и статьей 13 Положения о порядке прохождения военной службы, не может являться основанием для прекращения выплаты ему денежного довольствия."],
["19","При разрешении споров военнослужащих, назначенных с их согласия в связи с проводимыми организационно-штатными мероприятиями на воинские должности с…","","","19. При разрешении споров военнослужащих, назначенных с их согласия в связи с проводимыми организационно-штатными мероприятиями на воинские должности с меньшими месячными окладами, следует учитывать, что в соответствии с постановлением Правительства Российской Федерации от 17 марта 1999 года N 305 \"О сохранении за военнослужащими, проходящими военную службу по контракту, месячных окладов по ранее занимаемым воинским должностям при переводе их на воинские должности с меньшими месячными окладами в связи с реформированием Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, в которых законом предусмотрена военная служба\" таким военнослужащим выплата сохраненного оклада по прежней воинской должности производится при прохождении военной службы на той воинской должности, на которую они были назначены с сохранением указанного оклада. Назначение впоследствии на иную воинскую должность не влечет выплату военнослужащему ранее сохраненного оклада по прежней воинской должности."],
["20","Судам следует иметь в виду, что в силу части 30 статьи 2 Федерального закона \"О денежном довольствии военнослужащих и предоставлении им отдельных…","","","20. Судам следует иметь в виду, что в силу части 30 статьи 2 Федерального закона \"О денежном довольствии военнослужащих и предоставлении им отдельных выплат\" военнослужащему, в отношении которого в качестве меры пресечения применено заключение под стражу, выплата денежного довольствия приостанавливается со дня заключения его под стражу и возобновляется со дня освобождения из-под стражи. При этом в случае вынесения военнослужащему оправдательного приговора или прекращения в отношении его уголовного дела по реабилитирующим основаниям денежное довольствие выплачивается в полном объеме за весь период содержания под стражей.\nВоеннослужащим, осужденным к отбыванию наказания в дисциплинарных воинских частях, со дня вступления приговора в законную силу и до назначения на воинские должности по отбытии наказания или до увольнения с военной службы денежное довольствие выплачивается в порядке и размерах, которые установлены для военнослужащих Вооруженных Сил Российской Федерации.\nПраво на отдых"],
["21","Дополнительные сутки (дополнительное время) отдыха военнослужащим, проходящим военную службу по контракту, предоставляются в соответствии с пунктами…","","","21. Дополнительные сутки (дополнительное время) отдыха военнослужащим, проходящим военную службу по контракту, предоставляются в соответствии с пунктами 1 и 3 статьи 11 Федерального закона \"О статусе военнослужащих\" с учетом положений статей 219, 220, 234 Устава внутренней службы Вооруженных Сил Российской Федерации, утвержденного Указом Президента Российской Федерации от 10 ноября 2007 года N 1495, статьи 29 Положения о порядке прохождения военной службы, а также с учетом требований, изложенных в Порядке учета служебного времени и предоставления дополнительных суток отдыха (приложение N 2 к Положению о порядке прохождения военной службы).\nИсходя из названных положений предусмотрены следующие сроки (периоды) предоставления дополнительных суток (дополнительного времени) отдыха: в другие дни недели, в период основного отпуска путем его увеличения за счет присоединения дополнительных суток отдыха, в период дополнительного времени отдыха до дня начала основного отпуска. При этом общая продолжительность ежегодного основного отпуска с учетом дополнительного времени (дополнительных суток) отдыха не может превышать 60 суток, не считая времени, необходимого для проезда к месту использования отпуска и обратно.\nВ тех случаях, когда военнослужащему не было предоставлено дополнительное время (дополнительные сутки) отдыха вместе с основным отпуском за истекший год в следующем календарном году, срок, с которого исчисляется нарушение права военнослужащего на предоставление дополнительного времени (дополнительных суток) отдыха за предшествующий период, начинает исчисляться с 1 января года, следующего за годом, в который основной отпуск должен был быть перенесен.\nПеренос времени отдыха военнослужащего на следующий календарный год допускается в отношении как основного (дополнительного) отпуска, так и дополнительного времени (дополнительных суток) отдыха.\nСудам также следует учитывать, что согласно пункту 3 статьи 11 Федерального закона \"О статусе военнослужащих\" военнослужащим, проходящим военную службу по контракту, участвующим в мероприятиях, которые проводятся при необходимости без ограничения общей продолжительности еженедельного служебного времени, по их просьбе вместо предоставления дополнительных суток отдыха может выплачиваться денежная компенсация в размере денежного содержания за каждые положенные дополнительные сутки отдыха.\nПомимо дополнительного времени (дополнительных суток) отдыха, в соответствии с пунктом 12 статьи 11 Федерального закона \"О статусе военнослужащих\" военнослужащим предоставляются дополнительные отпуска, установленные нормативными правовыми актами Российской Федерации."],
["22","В силу подпункта 11 пункта 1 статьи 16 Федерального закона от 12 января 1995 года N 5-ФЗ \"О ветеранах\" военнослужащим - ветеранам боевых действий…","","","22. В силу подпункта 11 пункта 1 статьи 16 Федерального закона от 12 января 1995 года N 5-ФЗ \"О ветеранах\" военнослужащим - ветеранам боевых действий основной отпуск предоставляется в удобное для них время.\nПри этом согласно пунктам 5.1 и 12 статьи 11 Федерального закона \"О статусе военнослужащих\" военнослужащим - ветеранам боевых действий, указанным в Федеральном законе \"О ветеранах\", помимо основного отпуска, предоставляется дополнительный отпуск продолжительностью 15 суток. В год увольнения с военной службы указанный отпуск предоставляется военнослужащему в полном объеме."],
["23","Исходя из содержания абзаца шестого пункта 10 статьи 11 Федерального закона \"О статусе военнослужащих\" отпуск по личным обстоятельствам…","","","23. Исходя из содержания абзаца шестого пункта 10 статьи 11 Федерального закона \"О статусе военнослужащих\" отпуск по личным обстоятельствам продолжительностью 30 суток предоставляется также военнослужащим, проходящим в соответствии с федеральными законами военную службу после достижения ими предельного возраста пребывания на военной службе и не использовавшим указанный отпуск ранее. При этом отпуск по личным обстоятельствам предоставляется при общей продолжительности военной службы таких военнослужащих 20 лет и более.\nНеобходимо учитывать, что, по смыслу пункта 2 статьи 10 Федерального закона \"О статусе военнослужащих\", общая продолжительность военной службы военнослужащего включает в себя все время его военной службы как по призыву, так и по контракту, в том числе и в случаях повторного поступления на военную службу. Определение общей продолжительности военной службы производится в календарном исчислении. Законодательство Российской Федерации не предусматривает, например, возможности зачета службы в органах внутренних дел в общую продолжительность военной службы для предоставления отпуска по личным обстоятельствам."],
["24","В соответствии с пунктом 17 статьи 29 Положения о порядке прохождения военной службы военнослужащим-супругам, проходящим военную службу по контракту,…","","","24. В соответствии с пунктом 17 статьи 29 Положения о порядке прохождения военной службы военнослужащим-супругам, проходящим военную службу по контракту, основной отпуск с учетом их желания предоставляется одновременно.\nВоеннослужащим, проходящим военную службу по контракту, супруги которых находятся в отпуске по беременности и родам, основной отпуск также предоставляется с учетом желания военнослужащих.\nВ случае когда один из работающих родителей (опекун, попечитель) является военнослужащим или когда оба родителя (опекуны, попечители) являются военнослужащими, проходящими военную службу по контракту, согласно пункту 2 статьи 32 Положения о порядке прохождения военной службы для ухода за детьми-инвалидами таким родителям (опекунам, попечителям) предоставляются четыре дополнительных выходных дня в месяц.\nУказанные выходные дни могут быть использованы одним из родителей (опекуном, попечителем) либо разделены родителями (опекунами, попечителями) между собой по их усмотрению.\nПраво на жилище"],
["25","При рассмотрении исков (заявлений) военнослужащих, связанных с осуществлением ими права на жилище, необходимо иметь в виду, что основания и порядок…","","","25. При рассмотрении исков (заявлений) военнослужащих, связанных с осуществлением ими права на жилище, необходимо иметь в виду, что основания и порядок обеспечения военнослужащих жильем регулируются как нормами Федерального закона \"О статусе военнослужащих\", так и нормами Жилищного кодекса Российской Федерации (далее - ЖК РФ), принятыми в соответствии с ЖК РФ другими федеральными законами, а также изданными в соответствии с ними указами Президента Российской Федерации, постановлениями Правительства Российской Федерации, нормативными правовыми актами федеральных органов исполнительной власти (федеральных государственных органов), принятыми законами и иными нормативными правовыми актами субъектов Российской Федерации, нормативными правовыми актами органов местного самоуправления.\nВ связи с изложенным судам следует исходить из того, что гарантированное статьей 15 Федерального закона \"О статусе военнослужащих\" право военнослужащих и совместно проживающих с ними членов их семей на обеспечение жилыми помещениями в форме предоставления денежных средств за счет средств федерального бюджета на приобретение или строительство жилых помещений либо предоставления жилых помещений должно реализовываться в порядке и на условиях, установленных федеральными законами и иными нормативными правовыми актами Российской Федерации.\nАбзац исключен. - Постановление Пленума Верховного Суда РФ от 28.10.2025 N 21."],
["26","Обратить внимание судов на то, что согласно части 2 статьи 15, части 5 статьи 57 ЖК РФ, пунктам 1 и 14 статьи 15 Федерального закона \"О статусе…","","","26. Обратить внимание судов на то, что согласно части 2 статьи 15, части 5 статьи 57 ЖК РФ, пунктам 1 и 14 статьи 15 Федерального закона \"О статусе военнослужащих\" предоставляемое военнослужащему жилое помещение по договору социального найма или в собственность, в том числе по избранному постоянному месту жительства, должно отвечать установленным санитарным и техническим правилам и нормам, иным требованиям законодательства и должно находиться в границах соответствующего населенного пункта.\nСудам также следует учитывать, что в силу пункта 19 статьи 15 Федерального закона \"О статусе военнослужащих\" в случае, если военнослужащий, проходящий военную службу по истечении срока контракта в добровольном порядке до получения жилого помещения, отказывается от предложенного жилого помещения, которое расположено по избранному месту жительства, а также изъявляет желание изменить ранее избранное место жительства, такому военнослужащему предоставляется жилищная субсидия.\nРазрешая споры, связанные с предоставлением военнослужащим жилого помещения либо жилищной субсидии вместо ранее предложенного жилого помещения, судам необходимо учитывать конкретные обстоятельства дела, интересы военнослужащих и членов их семей и другие заслуживающие внимания обстоятельства."],
["27","Согласно пункту 5 статьи 15 Федерального закона \"О статусе военнослужащих\" в случае освобождения жилых помещений, занимаемых военнослужащими и…","","","27. Согласно пункту 5 статьи 15 Федерального закона \"О статусе военнослужащих\" в случае освобождения жилых помещений, занимаемых военнослужащими и совместно проживающими с ними членами их семей, за исключением жилых помещений, находящихся в их собственности, указанные помещения предоставляются другим военнослужащим и членам их семей.\nЕсли военнослужащий реализовал свое право на жилое помещение по договору социального найма в порядке, предусмотренном Федеральным законом \"О статусе военнослужащих\", и не может представить документы о его освобождении, повторное обеспечение такого военнослужащего жилым помещением по договору социального найма осуществляется в общем порядке согласно нормам ЖК РФ с учетом ранее полученного жилого помещения от федерального органа исполнительной власти (федерального государственного органа), в котором федеральным законом предусмотрена военная служба, и других заслуживающих внимания обстоятельств.\nРасторжение супругой (супругом) военнослужащего в отношении себя на основании статьи 83 ЖК РФ договора социального найма жилого помещения в связи с выездом к месту военной службы супруга (супруги) в другой населенный пункт не относится к действиям по намеренному ухудшению жилищных условий (статья 53 ЖК РФ)."],
["28","В соответствии с пунктом 17 статьи 15 Федерального закона \"О статусе военнослужащих\" денежные средства на приобретение или строительство жилых…","","","28. В соответствии с пунктом 17 статьи 15 Федерального закона \"О статусе военнослужащих\" денежные средства на приобретение или строительство жилых помещений либо жилые помещения в собственность бесплатно или по договору социального найма вне очереди предоставляются военнослужащим-гражданам и гражданам, уволенным с военной службы, в том числе имеющим трех и более детей либо одного и более ребенка-инвалида, проживающих совместно с военнослужащими-гражданами и гражданами, уволенными с военной службы. При этом судам следует иметь в виду, что право на внеочередное обеспечение жильем военнослужащих, имеющих трех и более детей, которые проживают совместно с ними, законодательством не поставлено в зависимость от достижения детьми возраста 18 лет.\nВо избежание нарушения прав военнослужащих на дополнительную общую площадь жилого помещения в соответствии с пунктом 2 статьи 15.1 Федерального закона \"О статусе военнослужащих\" судам следует исходить из того, что такое право сохраняется за офицерами в воинском звании полковника, ему равном и выше, не только проходящими военную службу, но и уволенными с военной службы по достижении предельного возраста пребывания на военной службе, состоянию здоровья или в связи с организационно-штатными мероприятиями. Иные категории военнослужащих (например, командиры воинских частей в воинском звании до подполковника, капитана 2 ранга включительно) имеют право на дополнительную общую площадь жилого помещения только в период прохождения военной службы.\nПри наличии права на дополнительную общую площадь жилого помещения в соответствии с законодательством Российской Федерации по нескольким основаниям увеличение размера общей площади жилого помещения производится по одному из них (пункт 2 статьи 15.1 Федерального закона \"О статусе военнослужащих\").\nВ тех случаях, когда военнослужащему невозможно предоставить по установленным нормам жилое помещение, в том числе с учетом его права на дополнительную общую площадь жилого помещения, допускается превышение нормы предоставления жилого помещения с учетом конструктивных и технических параметров многоквартирного дома, но не более установленных норм (пункты 1 и 3 статьи 15.1 Федерального закона \"О статусе военнослужащих\").\nПредусмотренное абзацем четвертым пункта 16 статьи 15 Федерального закона \"О статусе военнослужащих\" право военнослужащих на предоставление жилого помещения в собственность общей площадью, превышающей установленную норму предоставления площади жилого помещения, может быть реализовано только с их согласия, поскольку в этом случае военнослужащие производят оплату общей площади жилого помещения, превышающей норму предоставления площади жилого помещения, за счет собственных средств. Порядок оплаты общей площади жилого помещения, превышающей норму предоставления площади жилого помещения, устанавливается Правительством Российской Федерации."],
["29","При разрешении споров о праве членов семей военнослужащих, погибших (умерших) в период прохождения военной службы, и членов семей граждан,…","","","29. При разрешении споров о праве членов семей военнослужащих, погибших (умерших) в период прохождения военной службы, и членов семей граждан, проходивших военную службу по контракту и погибших (умерших) после увольнения с военной службы, на жилое помещение необходимо учитывать, что в силу пункта 1.1 статьи 15.1 и пункта 3.1 статьи 24 Федерального закона \"О статусе военнослужащих\" жилищные субсидии либо жилые помещения предоставляются им с учетом права погибшего (умершего) военнослужащего или гражданина, уволенного с военной службы, в том числе на дополнительную общую площадь жилого помещения на дату его гибели (смерти).\nСоциальные гарантии и компенсации при исполнении обязанностей военной службы"],
["30","В силу пункта 9 статьи 2 Федерального закона \"О статусе военнослужащих\" военнослужащие, граждане, уволенные с военной службы, члены их семей, имеющие…","","","30. В силу пункта 9 статьи 2 Федерального закона \"О статусе военнослужащих\" военнослужащие, граждане, уволенные с военной службы, члены их семей, имеющие право на социальные гарантии и компенсации в соответствии с Федеральным законом \"О статусе военнослужащих\", пользуются социальными гарантиями и компенсациями, установленными для граждан федеральными конституционными законами, федеральными законами и иными нормативными правовыми актами Российской Федерации.\nПри этом необходимо исходить из того, что право на предоставление социальных гарантий и компенсаций членам семей военнослужащих непосредственно вытекает из факта исполнения военнослужащими обязанностей военной службы (например, предоставление отпуска без сохранения заработной платы до 14 календарных дней в году - статья 128 ТК РФ; социальные гарантии в области образования - пункт 5 части 7 статьи 71 Федерального закона от 29 декабря 2012 года N 273-ФЗ \"Об образовании в Российской Федерации\") и наступает при определенных условиях (например, в случае смерти военнослужащего вследствие увечья (ранения, травмы, контузии) либо заболеваний, полученных им при исполнении обязанностей военной службы, в том числе при участии в проведении контртеррористических операций и (или) иных мероприятий по борьбе с терроризмом)."],
["31","Исходя из положений частей 8 и 9 статьи 3 Федерального закона \"О денежном довольствии военнослужащих и предоставлении им отдельных выплат\" в случае…","","","31. Исходя из положений частей 8 и 9 статьи 3 Федерального закона \"О денежном довольствии военнослужащих и предоставлении им отдельных выплат\" в случае гибели (смерти) военнослужащего или гражданина, призванного на военные сборы, наступившей при исполнении обязанностей военной службы, либо его смерти, наступившей вследствие увечья (ранения, травмы, контузии) или заболевания, полученных при исполнении обязанностей военной службы, а также в случае гибели (смерти) гражданина, пребывающего в добровольческом формировании, наступившей при исполнении обязанностей по контракту о пребывании в добровольческом формировании, либо его смерти, наступившей вследствие увечья (ранения, травмы, контузии) или заболевания, полученных при исполнении обязанностей по контракту о пребывании в добровольческом формировании, членам семьи погибшего (умершего) военнослужащего, или гражданина, проходившего военные сборы, или гражданина, пребывавшего в добровольческом формировании, выплачиваются установленные этим законом пособия и компенсации.\nРазрешая споры, связанные с предоставлением социальных гарантий и компенсаций членам семей указанных лиц, судам следует учитывать положения пункта 2 статьи 37 Федерального закона \"О воинской обязанности и военной службе\" и иных нормативных правовых актов, устанавливающих случаи, когда военнослужащий (гражданин, пребывающий в добровольческом формировании) не считается исполняющим обязанности военной службы (обязанности по контракту о пребывании в добровольческом формировании)."],
["32","Исключен","","","32. Исключен. - Постановление Пленума Верховного Суда РФ от 28.10.2025 N 21."],
["33","Судам следует иметь в виду, что Закон Российской Федерации от 19 февраля 1993 года N 4520-1 \"О государственных гарантиях и компенсациях для лиц,…","","","33. Судам следует иметь в виду, что Закон Российской Федерации от 19 февраля 1993 года N 4520-1 \"О государственных гарантиях и компенсациях для лиц, работающих и проживающих в районах Крайнего Севера и приравненных к ним местностях\" распространяется на определенный круг лиц, непосредственно указанных в статье 1 этого закона. Военнослужащие, проходящие военную службу по контракту в районах Крайнего Севера и приравненных к ним местностях, в Законе не указаны, в связи с чем на них действие статьи 33 Закона не распространяется.\nПри рассмотрении дел, связанных с проездом военнослужащих, проходящих военную службу по контракту в районах Крайнего Севера и приравненных к ним местностях, надлежит учитывать, что в отношении их действует специальная норма, предусмотренная пунктом 1.1 статьи 20 Федерального закона \"О статусе военнослужащих\".\nСогласно названной норме военнослужащие, проходящие военную службу по контракту в районах Крайнего Севера и приравненных к ним местностях, в других местностях с неблагоприятными климатическими и (или) экологическими условиями, в том числе отдаленных, а также на территории субъектов Российской Федерации, входящих в Уральский, Сибирский и Дальневосточный федеральные округа, курсанты военных профессиональных образовательных организаций или военных образовательных организаций высшего образования до заключения с ними контракта о прохождении военной службы имеют право на проезд на безвозмездной основе железнодорожным, воздушным, водным и автомобильным (за исключением такси) транспортом один раз в год по территории Российской Федерации к месту использования основного (летнего каникулярного) отпуска и обратно.\nПри этом военнослужащие, проходящие военную службу по контракту за пределами территории Российской Федерации, имеют право на проезд на безвозмездной основе к месту использования основного (летнего каникулярного) отпуска на территории Российской Федерации и обратно.\nМатериальная и иные виды ответственности военнослужащих"],
["34","При рассмотрении споров, возникающих в связи с привлечением военнослужащих, граждан, призванных на военные сборы, в том числе пребывающих в…","","","34. При рассмотрении споров, возникающих в связи с привлечением военнослужащих, граждан, призванных на военные сборы, в том числе пребывающих в мобилизационном людском резерве, граждан, пребывающих в добровольческих формированиях, к материальной ответственности, судам следует учитывать, что основания и порядок привлечения названных лиц к материальной ответственности за ущерб, причиненный государству при исполнении обязанностей военной службы (обязанностей по контракту о пребывании в добровольческом формировании), определяются федеральными законами \"О воинской обязанности и военной службе\", \"О статусе военнослужащих\" и \"О материальной ответственности военнослужащих\".\nСогласно пунктам 1 и 4 статьи 8 Федерального закона \"О материальной ответственности военнослужащих\" возмещение ущерба, размер которого не превышает одного оклада месячного денежного содержания военнослужащего и одной ежемесячной надбавки за выслугу лет (двух окладов по воинской должности военнослужащего, проходящего военную службу по призыву, одного оклада по воинской должности, предусмотренной штатом воинской части, и одного оклада по воинскому званию гражданина, призванного на военные сборы), производится по приказу командира (начальника) воинской части. Приказ о привлечении к материальной ответственности может быть оспорен в соответствующем военном суде.\nВопрос о возмещении ущерба, размер которого превышает один оклад месячного денежного содержания военнослужащего и одну ежемесячную надбавку за выслугу лет (два оклада по воинской должности военнослужащего, проходящего военную службу по призыву, один оклад по воинской должности, предусмотренной штатом воинской части, и один оклад по воинскому званию гражданина, призванного на военные сборы), решается судом по иску командира (начальника) воинской части.\nИск о возмещении ущерба, причиненного командиром (начальником) воинской части, предъявляется вышестоящим в порядке подчиненности командиром (начальником). В случае причинения ущерба командиром воинской части, уволенным с военной службы, иск о возмещении ущерба предъявляется командиром воинской части, которой причинен ущерб.\nВ силу пункта 4 статьи 3 Федерального закона \"О материальной ответственности военнослужащих\" срок привлечения военнослужащего к материальной ответственности составляет три года со дня обнаружения ущерба.\nДнем обнаружения ущерба следует считать день, когда командир (начальник), а в соответствующих случаях вышестоящие в порядке подчиненности органы военного управления и воинские должностные лица узнали или должны были узнать о наличии материального ущерба, причиненного военнослужащим (день составления рапорта, акта проверки, справки, служебного донесения и т.п.).\nТечение срока привлечения военнослужащего к материальной ответственности приостанавливается и (или) прерывается по основаниям, предусмотренным статьей 3 Федерального закона \"О материальной ответственности военнослужащих\".\nКомандиры (начальники), не принявшие необходимых мер по возмещению виновными лицами причиненного воинской части ущерба, привлекаются к материальной ответственности в течение одного года со дня истечения срока привлечения к материальной ответственности указанных лиц, рассчитанного по правилам, предусмотренным абзацами первым - пятым пункта 4 статьи 3 Федерального закона \"О материальной ответственности военнослужащих\"."],
["35","Возмещение ущерба, причиненного военнослужащими не при исполнении обязанностей военной службы или при исполнении таких обязанностей, но имуществу, не…","","","35. Возмещение ущерба, причиненного военнослужащими не при исполнении обязанностей военной службы или при исполнении таких обязанностей, но имуществу, не находящемуся в федеральной собственности и не закрепленному за воинскими частями, либо ущерба, причиненного физическим лицам, осуществляется в порядке, предусмотренном Гражданским кодексом Российской Федерации.\nПри этом судам следует иметь в виду, что приведение военнослужащим себя в состояние опьянения, а также другие обстоятельства, перечисленные в пункте 2 статьи 37 Федерального закона \"О воинской обязанности и военной службе\", не освобождают его от ответственности, в том числе материальной, за нарушение обязанностей военной службы."],
["36","Если административное правонарушение совершено военнослужащим или гражданином, призванным на военные сборы, за исключением случаев, когда за такое…","","","36. Если административное правонарушение совершено военнослужащим или гражданином, призванным на военные сборы, за исключением случаев, когда за такое административное правонарушение это лицо несет административную ответственность на общих основаниях, в соответствии с частью 2 статьи 24.5 КоАП РФ производство по делу об административном правонарушении подлежит прекращению для привлечения указанного лица к дисциплинарной ответственности.\nПри этом согласно пункту 8 статьи 28.2 Федерального закона \"О статусе военнослужащих\" срок давности привлечения к дисциплинарной ответственности составляет один год со дня совершения дисциплинарного проступка, за исключением случаев, когда федеральными законами установлены иные сроки давности привлечения военнослужащих к дисциплинарной ответственности.\nСудам необходимо учитывать, что в соответствии со статьей 94 Дисциплинарного устава Вооруженных Сил Российской Федерации, утвержденного Указом Президента Российской Федерации от 10 ноября 2007 года N 1495, если грубым дисциплинарным проступком является административное правонарушение, то дисциплинарный арест может быть применен только в том случае, когда за такое административное правонарушение КоАП РФ предусмотрено административное наказание в виде административного ареста.\nЗаявления об оспаривании действий и решений воинского должностного лица, связанных с применением в отношении виновных лиц дисциплинарных взысканий в указанных случаях, рассматриваются военными судами в порядке, предусмотренном главой 22 КАС РФ."],
["37","За совершение административных правонарушений, предусмотренных в части 2 статьи 2.5 КоАП РФ, военнослужащие и призванные на военные сборы граждане…","","","37. За совершение административных правонарушений, предусмотренных в части 2 статьи 2.5 КоАП РФ, военнослужащие и призванные на военные сборы граждане несут административную ответственность на общих основаниях.\nПри назначении военнослужащим, проходящим военную службу по призыву, административных наказаний за совершение административных правонарушений, предусмотренных частью 2 статьи 12.7 и частью 3 статьи 12.8 КоАП РФ, судья не вправе назначить предусмотренные их санкциями наказания: административный штраф (часть 6 статьи 3.5), административный арест (часть 2 статьи 3.9) или обязательные работы (часть 3 статьи 3.13), поскольку к указанной категории лиц не применяются данные виды наказаний, а также судья не вправе заменить наказание другим, более мягким, поскольку в соответствии с частью 3 статьи 3.3 КоАП РФ за административное правонарушение может быть назначено лишь то административное наказание, которое указано в санкции применяемой статьи Кодекса.\nПоскольку в таких случаях у судьи нет оснований для вынесения постановления о назначении административного наказания, по смыслу части 2 статьи 24.5 и пункта 1 части 2 статьи 29.9 КоАП РФ производство по делу подлежит прекращению, а материалы дела - передаче командиру (начальнику) воинской части, где виновный проходит военную службу, для применения иных мер воздействия в соответствии с законодательством Российской Федерации.\nВ случае привлечения указанного военнослужащего к дисциплинарной ответственности она должна применяться не за административное правонарушение, а по основаниям, установленным статьей 28.2 Федерального закона \"О статусе военнослужащих\", и в порядке, предусмотренном этим Федеральным законом и Дисциплинарным уставом Вооруженных Сил Российской Федерации."],
["38","Военные суды должны оценивать не только обоснованность привлечения к дисциплинарной ответственности военнослужащего, но и соразмерность примененного…","","","38. Военные суды должны оценивать не только обоснованность привлечения к дисциплинарной ответственности военнослужащего, но и соразмерность примененного дисциплинарного взыскания тяжести совершенного проступка и степени его вины. Под несоразмерностью примененного к военнослужащему дисциплинарного взыскания следует понимать очевидное несоответствие примененного дисциплинарного взыскания тяжести совершенного проступка, например, если будет установлено, что командир (начальник) не учел все обстоятельства, которые надлежит учитывать в силу закона.\nПри этом суды не вправе определять вид дисциплинарного взыскания, которое надлежит применить к военнослужащему.\nСудам следует учитывать, что в соответствии со статьей 96 Дисциплинарного устава Вооруженных Сил Российской Федерации дисциплинарное взыскание - предупреждение о неполном служебном соответствии - может быть применено только к военнослужащему, проходящему военную службу по контракту, занимающему штатную воинскую должность. К военнослужащему, состоящему в распоряжении командира (начальника), указанное дисциплинарное взыскание не применяется.\nВ случае систематического нарушения должностных и (или) специальных обязанностей до окончания срока действия данного взыскания военнослужащий может быть представлен к снижению в воинской должности или досрочному увольнению с военной службы.\nУвольнение с военной службы"],
["39","При увольнении военнослужащих с военной службы по достижении предельного возраста пребывания на военной службе, по состоянию здоровья или в связи с…","","","39. При увольнении военнослужащих с военной службы по достижении предельного возраста пребывания на военной службе, по состоянию здоровья или в связи с организационно-штатными мероприятиями за ними сохраняются социальные гарантии и компенсации, предусмотренные Федеральным законом \"О статусе военнослужащих\" и иными нормативными правовыми актами.\nПри наличии у военнослужащего одновременно нескольких оснований для увольнения с военной службы, предусмотренных статьей 51 Федерального закона \"О воинской обязанности и военной службе\" (за исключением случаев, когда увольнение производится по основаниям, предусмотренным подпунктами \"д\", \"д.1\", \"д.2\", \"е\", \"е.1\" и \"з\" пункта 1 и подпунктами \"в\", \"г\", \"д\", \"е.1\", \"е.2\", \"к\" и \"л\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\"), он имеет право выбора одного из них по своему усмотрению.\nПри этом судам следует учитывать, что, если увольнение с военной службы производится по основанию, предусмотренному подпунктом \"г\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\", в связи с отказом в допуске к государственной тайне или прекращением указанного допуска, право выбора иного основания для увольнения с военной службы не предоставляется, при условии что отказ в допуске или прекращение допуска к государственной тайне связаны со следующими обстоятельствами: с наличием у военнослужащего статуса обвиняемого (подсудимого) по уголовному делу о совершенном по неосторожности преступлении против государственной власти или об умышленном преступлении; наличием у военнослужащего непогашенной или неснятой судимости за данные преступления; прекращением в отношении его уголовного дела (уголовного преследования) по нереабилитирующим основаниям, если со дня прекращения такого уголовного дела (уголовного преследования) не истек срок, равный сроку давности привлечения к уголовной ответственности за совершение этих преступлений; уклонением военнослужащего от проверочных мероприятий и (или) сообщением им заведомо ложных анкетных данных; нарушением военнослужащим требований законодательства Российской Федерации о государственной тайне; включением военнослужащего в реестр иностранных агентов либо выявлением в результате проверочных мероприятий действий военнослужащего, создающих угрозу безопасности Российской Федерации; вынесением Федеральной службой безопасности Российской Федерации и (или) ее территориальным органом заключения о нецелесообразности допуска военнослужащего к государственной тайне."],
["40","В случае сокращения занимаемой воинской должности и при невозможности назначения военнослужащего, проходящего военную службу по контракту, на равную…","","","40. В случае сокращения занимаемой воинской должности и при невозможности назначения военнослужащего, проходящего военную службу по контракту, на равную воинскую должность и отсутствии его согласия с назначением на высшую или низшую воинскую должность такой военнослужащий может быть досрочно уволен с военной службы в связи с организационно-штатными мероприятиями (подпункт \"а\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\").\nПо смыслу нормативных положений, регулирующих военную службу и порядок ее прохождения, при сокращении воинской должности, занимаемой военнослужащим, и отсутствии вакантных воинских должностей в военном округе, в котором он проходит военную службу, другая воинская должность должна предлагаться военнослужащему, изъявившему желание на назначение на низшие или высшие воинские должности, в масштабе Вооруженных Сил Российской Федерации, а военнослужащим других войск, воинских формирований и органов - в масштабах федерального органа исполнительной власти (федерального государственного органа), в котором они проходят военную службу."],
["41","Досрочное увольнение с военной службы по подпункту \"в\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\" в связи с…","","","41. Досрочное увольнение с военной службы по подпункту \"в\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\" в связи с невыполнением условий контракта может применяться к военнослужащим в порядке дисциплинарного взыскания и в порядке аттестации с учетом соответствия военнослужащего предъявляемым к нему требованиям.\nНевыполнением условий контракта как основанием для досрочного увольнения военнослужащего с военной службы следует считать лишь значительные (существенные) отступления от требований законодательства о воинской обязанности и военной службе, которые могут выражаться, в частности, в совершении виновных действий (бездействия), свидетельствующих об отсутствии у военнослужащего необходимых качеств для надлежащего выполнения обязанностей военной службы; совершении одного из грубых дисциплинарных проступков, составы которых перечислены в пункте 2 статьи 28.5 Федерального закона \"О статусе военнослужащих\"; совершении дисциплинарного проступка при наличии у него неснятых дисциплинарных взысканий; совершении уголовно наказуемого деяния или административного правонарушения, за которое военнослужащий несет ответственность на общих основаниях; иных юридически значимых обстоятельств, позволяющих в силу специфики служебной деятельности военнослужащего сделать вывод о том, что он перестал удовлетворять требованиям законодательства о воинской обязанности и военной службе, предъявляемым к военнослужащим, проходящим военную службу по контракту.\nЕсли военнослужащий по своим деловым и личным качествам не соответствует требованиям, предъявляемым к лицам, проходящим военную службу (о чем может свидетельствовать, например, наличие у него неснятых дисциплинарных взысканий), его досрочное увольнение с военной службы возможно только по результатам аттестации, в том числе внеочередной."],
["42","Решение о досрочном увольнении военнослужащего с военной службы в связи с переводом на федеральную государственную гражданскую службу (подпункт \"ж\"…","","","42. Решение о досрочном увольнении военнослужащего с военной службы в связи с переводом на федеральную государственную гражданскую службу (подпункт \"ж\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\") должно быть основано не только на волеизъявлении военнослужащего, но и на объективных данных, гарантирующих возможность его поступления на конкретную должность государственной гражданской службы."],
["43","Юридически значимыми обстоятельствами, подлежащими установлению судами по делам об оспаривании досрочного увольнения с военной службы по подпункту…","","","43. Юридически значимыми обстоятельствами, подлежащими установлению судами по делам об оспаривании досрочного увольнения с военной службы по подпункту \"е.1\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\", являются не только обстоятельства, связанные с установлением факта нарушения запретов, ограничений и обязанностей, установленных пунктом 7 статьи 10 и статьей 27.1 Федерального закона \"О статусе военнослужащих\" и другими федеральными законами, но и обстоятельства, связанные с соблюдением воинскими должностными лицами процедуры досрочного увольнения военнослужащего с военной службы по указанному основанию.\nПри рассмотрении споров о применении взыскания, предусмотренного подпунктом \"е.1\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\", необходимо учитывать, что оно применяется не позднее шести месяцев со дня поступления информации о совершении военнослужащим коррупционного правонарушения, не считая периодов временной нетрудоспособности военнослужащего, нахождения его в отпуске, и не позднее трех лет со дня совершения им коррупционного правонарушения. В указанные сроки не включается время производства по уголовному делу.\nПо смыслу Федерального закона \"О воинской обязанности и военной службе\", под актом о применении к военнослужащему взыскания - досрочного увольнения с военной службы по основанию, предусмотренному подпунктом \"е.1\" пункта 2 статьи 51 названного закона, понимается приказ воинского должностного лица, обладающего правом его издания.\nВ тех случаях, когда к военнослужащему не может быть применено взыскание в виде досрочного увольнения с военной службы по основанию, предусмотренному подпунктом \"е.1\" пункта 2 статьи 51 Федерального закона \"О воинской обязанности и военной службе\" (например, к гражданину, осужденному к лишению свободы, призванному на военную службу по мобилизации или в военное время в Вооруженные Силы Российской Федерации либо заключившему в период мобилизации, в период военного положения или в военное время контракт о прохождении военной службы в Вооруженных Силах Российской Федерации), уполномоченное воинское должностное лицо вправе применить иное дисциплинарное взыскание с учетом тяжести коррупционного правонарушения, обстоятельств, при которых оно совершено, соблюдения военнослужащим других ограничений и запретов, требований о предотвращении или об урегулировании конфликта интересов и исполнения им обязанностей, установленных в целях противодействия коррупции, а также предшествующих результатов исполнения им своих должностных обязанностей."],
["44","В соответствии с подпунктом \"а\" пункта 3 статьи 51 Федерального закона \"О воинской обязанности и военной службе\" военнослужащий в случае…","","","44. В соответствии с подпунктом \"а\" пункта 3 статьи 51 Федерального закона \"О воинской обязанности и военной службе\" военнослужащий в случае существенного и (или) систематического нарушения в отношении его условий контракта о прохождении военной службы со стороны федерального органа исполнительной власти (федерального государственного органа), в котором федеральным законом предусмотрена военная служба, имеет право на досрочное увольнение с военной службы.\nСущественным нарушением условий контракта со стороны федерального органа исполнительной власти (федерального государственного органа), в котором федеральным законом предусмотрена военная служба, может быть признано такое нарушение, из-за которого военнослужащий лишился возможности осуществлять свои конституционные права, либо нарушение, лишающее военнослужащего или членов его семьи возможности воспользоваться наиболее значимыми для них правами, социальными гарантиями и компенсациями, предусмотренными законодательством о порядке прохождения военной службы и статусе военнослужащих.\nПри разрешении заявлений об оспаривании отказа в увольнении с военной службы в связи с нарушением условий контракта о прохождении военной службы со стороны федерального органа исполнительной власти (федерального государственного органа), в котором предусмотрена военная служба, вопрос о том, являются ли допущенные в отношении военнослужащего нарушения условий контракта существенными, должен решаться судом индивидуально по каждому конкретному делу с учетом таких обстоятельств, как семейное и материальное положение военнослужащего, место его военной службы и условия ее прохождения, а также других данных.\nСистематическим нарушением условий контракта должны признаваться многократные нарушения предусмотренных законодательством о статусе военнослужащих прав военнослужащего (повторяющиеся более двух раз) в течение непродолжительного времени."],
["45","Судам следует учитывать, что признание офицеров или прапорщиков (мичманов) ограниченно годными к военной службе на основании подпункта \"б\" пункта 3…","","","45. Судам следует учитывать, что признание офицеров или прапорщиков (мичманов) ограниченно годными к военной службе на основании подпункта \"б\" пункта 3 статьи 51 Федерального закона \"О воинской обязанности и военной службе\" не предполагает принуждение их к дальнейшему прохождению военной службы, поскольку решение вопроса о сохранении или прекращении статуса таких военнослужащих зависит от их свободного волеизъявления. В случае увольнения с военной службы, если общая продолжительность военной службы составляет 10 лет и более, такие военнослужащие не могут быть без их согласия сняты с учета в качестве нуждающихся в жилых помещениях по последнему перед увольнением месту военной службы и обеспечиваются жилищной субсидией или жилыми помещениями в порядке, предусмотренном Федеральным законом \"О статусе военнослужащих\" для военнослужащих.\nПри этом признание военно-врачебной комиссией такого военнослужащего ограниченно годным к военной службе дает ему право, но не обязывает досрочно увольняться с военной службы и не лишает его права продолжать военную службу на должности, позволяющей выполнять соответствующие состоянию здоровья общие, должностные и специальные обязанности. В связи с этим военнослужащие, принявшие решение продолжить военную службу, обеспечиваются жилыми помещениями в общем порядке в соответствии с существующей очередностью федеральными органами исполнительной власти (федеральными государственными органами), в которых федеральным законом предусмотрена военная служба."],
["46","В случаях досрочного увольнения военнослужащих с военной службы в связи с нарушением в отношении их условий контракта или в связи с признанием их…","","","46. В случаях досрочного увольнения военнослужащих с военной службы в связи с нарушением в отношении их условий контракта или в связи с признанием их ограниченно годными к военной службе по состоянию здоровья (подпункты \"а\" и \"б\" пункта 3 статьи 51 Федерального закона \"О воинской обязанности и военной службе\") они по основаниям и в порядке, которые предусмотрены пунктом 1 статьи 23 Федерального закона \"О статусе военнослужащих\", должны обеспечиваться жилищными субсидиями или жилыми помещениями как увольняющиеся соответственно в связи с организационно-штатными мероприятиями или по состоянию здоровья."],
["46(1)","Судам следует учитывать, что при досрочном увольнении военнослужащего по основанию, предусмотренному абзацем пятым подпункта \"в\" пункта 3 статьи 51…","","","46(1). Судам следует учитывать, что при досрочном увольнении военнослужащего по основанию, предусмотренному абзацем пятым подпункта \"в\" пункта 3 статьи 51 Федерального закона \"О воинской обязанности и военной службе\", по семейным обстоятельствам в связи с необходимостью ухода за ребенком, не достигшим возраста 18 лет, которого военнослужащий воспитывает без матери (отца) ребенка, необходимо принимать во внимание конкретные обстоятельства, имеющие значение для возможности надлежащей реализации родительских прав и обязанностей военнослужащим, а также интересы самих детей, реализация прав которых напрямую связана с возможностью их родителей осуществлять за ними надлежащий уход, потребность в котором обусловлена возрастом ребенка - до 18 лет (включая оценку состояния здоровья ребенка и зависящую от такой оценки возможность посещения им образовательной организации, в том числе дошкольной, наличие или отсутствие причин, препятствующих второму родителю участвовать в воспитании ребенка и уходе за ним, и другие заслуживающие внимания обстоятельства).\nРазрешая споры об увольнении с военной службы беременных военнослужащих женского пола, военнослужащих женского пола, имеющих детей в возрасте до трех лет, а также имеющих детей-инвалидов (одиноких матерей, имеющих детей в возрасте до 14 лет), необходимо учитывать социальные гарантии, предусмотренные для них пунктом 25 статьи 34 Положения о порядке прохождения военной службы.\nПри объявлении частичной или полной мобилизации военнослужащие женского пола, которые имеют одного ребенка и более в возрасте до 16 лет или срок беременности которых составляет не менее 22 недель, имеют право на досрочное увольнение с военной службы в соответствии с пунктом 5 статьи 17 Федерального закона \"О мобилизационной подготовке и мобилизации в Российской Федерации\"."],
["47","При проверке законности и обоснованности действий воинских должностных лиц, связанных с увольнением военнослужащего с военной службы по собственному…","","","47. При проверке законности и обоснованности действий воинских должностных лиц, связанных с увольнением военнослужащего с военной службы по собственному желанию, судам необходимо учитывать, что согласно пункту 6 статьи 51 Федерального закона \"О воинской обязанности и военной службе\" военнослужащий по заключению аттестационной комиссии может быть уволен с военной службы досрочно по собственному желанию при наличии у него уважительных причин.\nПод уважительными причинами понимаются обстоятельства, которые объективно не позволяют военнослужащему в полном объеме выполнять условия заключенного контракта.\nПоданный военнослужащим рапорт и соответствующее заключение аттестационной комиссии не являются безусловными основаниями для увольнения по собственному желанию, поскольку решение данного вопроса отнесено к полномочиям соответствующего воинского должностного лица."],
["48","Военнослужащие, имеющие право на обеспечение жилищными субсидиями или жилыми помещениями по договору социального найма или в собственность, не могут…","","","48. Военнослужащие, имеющие право на обеспечение жилищными субсидиями или жилыми помещениями по договору социального найма или в собственность, не могут быть уволены с военной службы с оставлением их на учете нуждающихся в жилых помещениях по последнему месту военной службы при отсутствии их согласия на такое увольнение.\nВ случаях когда указанные военнослужащие, настаивая на досрочном увольнении с военной службы, согласились уволиться с военной службы, оснований для их последующего восстановления на военной службе для обеспечения жилищной субсидией или жилым помещением не имеется, поскольку в этом случае требования пункта 1 статьи 23 Федерального закона \"О статусе военнослужащих\" не нарушаются.\nЕсли такие военнослужащие не соглашаются с увольнением их с военной службы без предоставления жилищной субсидии или жилого помещения, суд отказывает в удовлетворении их требований об увольнении с военной службы, поскольку указанные лица в соответствии с законом не могут быть уволены с военной службы.\nАбзац исключен. - Постановление Пленума Верховного Суда РФ от 28.10.2025 N 21."],
["49","В силу пункта 16 статьи 34 Положения о порядке прохождения военной службы военнослужащий, уволенный с военной службы, на день исключения из списков…","","","49. В силу пункта 16 статьи 34 Положения о порядке прохождения военной службы военнослужащий, уволенный с военной службы, на день исключения из списков личного состава воинской части должен быть полностью обеспечен установленным денежным довольствием, продовольственным и вещевым обеспечением. До проведения с военнослужащим всех необходимых расчетов он из списков личного состава воинской части без его согласия не исключается.\nВ случае если нарушение прав военнослужащего может быть устранено без восстановления его на военной службе или в списке личного состава воинской части, судом выносится решение только об устранении допущенного нарушения."],
["50","В случае признания судом увольнения с военной службы необоснованным военнослужащий в соответствии с пунктом 2 статьи 23 Федерального закона \"О…","","","50. В случае признания судом увольнения с военной службы необоснованным военнослужащий в соответствии с пунктом 2 статьи 23 Федерального закона \"О статусе военнослужащих\" подлежит восстановлению на военной службе в прежней (или с его согласия - равной или не ниже) должности с возмещением всех причиненных убытков. Причиненный таким увольнением моральный вред подлежит возмещению по решению суда на основании волеизъявления военнослужащего. Восстановление на военной службе производится путем отмены приказа об увольнении военнослужащего с военной службы. Отмена приказа об увольнении военнослужащего с военной службы производится воинским должностным лицом, издавшим приказ, или его прямым начальником. При этом признание военнослужащего не годным по состоянию здоровья к военной службе, истечение срока заключенного контракта или достижение им предельного возраста пребывания на военной службе на момент судебного разбирательства не может служить препятствием к принятию такого решения."],
["51","Принимая во внимание право прокурора вступать в процесс в случаях, предусмотренных статьей 45 ГПК РФ и статьей 39 КАС РФ, в том числе о…","","","51. Принимая во внимание право прокурора вступать в процесс в случаях, предусмотренных статьей 45 ГПК РФ и статьей 39 КАС РФ, в том числе о восстановлении военнослужащих на военной службе, военным судам следует извещать соответствующего прокурора о месте и времени рассмотрения соответствующих гражданских и административных дел.\nПри рассмотрении заявлений военнослужащих, связанных с нарушением их прав, свобод и охраняемых законом интересов, необходимо устанавливать причины и условия, способствовавшие нарушению воинскими должностными лицами и органами военного управления законодательства о воинской обязанности, военной службе и статусе военнослужащих, и при наличии к тому оснований реагировать на них в предусмотренном процессуальным законом порядке.\nОбратить внимание судов на то, что исполнение судебных решений по вопросам воинской обязанности, военной службы и статуса военнослужащих должно рассматриваться как элемент судебной защиты, а федеральные органы исполнительной власти (федеральные государственные органы) обязаны принимать необходимые меры по их реализации. Неправомерная задержка исполнения судебного решения должна рассматриваться как нарушение права на справедливое правосудие в разумные сроки."],
["52","В связи с принятием настоящего постановления признать утратившими силу:","","","52. В связи с принятием настоящего постановления признать утратившими силу:\nпункт 8 постановления Пленума Верховного Суда Российской Федерации от 6 февраля 2007 года N 6 \"Об изменении и дополнении некоторых постановлений Пленума Верховного Суда Российской Федерации по гражданским делам\".\nПредседатель Верховного Суда Российской Федерации В.М.ЛЕБЕДЕВ Секретарь Пленума, судья Верховного Суда Российской Федерации В.В.МОМОТОВ"]
];
